events.command:
/bin/bash -lc "find . -maxdepth 3 -type f -printf '%p\\n' | sort && printf '\\n--- tools ---\\n' && command -v ffmpeg && command -v python3 && python3 - <<'PY'
mods=['cv2','PIL','numpy','imageio','torch']
for m in mods:
 try:
  x=__import__(m); print(m, getattr(x,'__version__','ok'))
 except Exception as e: print(m,'MISSING',e)
PY"

/bin/bash -lc 'for t in python3 ffmpeg convert magick; do printf "$t: "; command -v "$t" || true; done
python3 - <<'"'PY'
mods=['cv2','PIL','numpy','imageio','scipy','skimage']
for m in mods:
 try:
  x=__import__(m); print(m, getattr(x,'__version__','ok'))
 except Exception as e: print(m,'MISSING',e)
PY"
